CREATE OR REPLACE FUNCTION check_and_grant_vip_status()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.spend_usd >= 10000.00 THEN
        UPDATE fans
        SET status_tag = 'VIP'
        WHERE user_registry = NEW.member_fan_pivot;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER on_spending_update_grant_vip
AFTER INSERT OR UPDATE ON membershipandspending
FOR EACH ROW
EXECUTE FUNCTION check_and_grant_vip_status();
